import{_ as l,C as A,o as r,c as p,a5 as t,b as n,w as e,a as i,E as s,a7 as o}from"./chunks/framework.QWVCgkrI.js";const D=JSON.parse('{"title":"フレーム生成 — 2枚の間を補い、表示を滑らかにする","description":"","frontmatter":{"title":"フレーム生成 — 2枚の間を補い、表示を滑らかにする","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"graphics","summary":"アップスケーリングとフレーム生成の違い、中間フレームを補間する仕組み、表示の滑らかさと入力遅延の関係を図とブラウザー実践で確かめる。","aliases":["フレーム生成","Frame Generation","フレーム補間","中間フレーム","オプティカルフロー","基礎FPS","表示FPS","DLSS Frame Generation","FSR Frame Generation"],"verification":"AMDのフレーム補間資料とNVIDIA Streamlineの開発者向け資料に照合（2026-11-13）"}},"headers":[],"relativePath":"graphics/postprocess/frame-generation.md","filePath":"graphics/postprocess/frame-generation.md"}'),m={name:"graphics/postprocess/frame-generation.md"};function B(d,a,h,f,u,c){const E=A("Mermaid");return r(),p("div",null,[a[3]||(a[3]=t('<h1 id="フレーム生成-—-2枚の間を補い、表示を滑らかにする" tabindex="-1">フレーム生成 — 2枚の間を補い、表示を滑らかにする <a class="header-anchor" href="#フレーム生成-—-2枚の間を補い、表示を滑らかにする" aria-label="Permalink to &quot;フレーム生成 — 2枚の間を補い、表示を滑らかにする&quot;">​</a></h1><p>走る物体を30 FPSで描くと、位置は約33 msごとに変わります。その間に物体が通りそうな位置を推定し、1枚挿入すると、動きを約17 ms間隔で見せられます。このように、<strong>描画したフレームの間に表示用の画像を追加する</strong>のが、補間を使うフレーム生成です。</p><p><a href="/study/practice/graphics/frame-generation-observation.html">フレーム生成の比較実践</a>では、同じシーンでオン・オフを切り替え、移動の滑らかさと、入力した色が画面に出るタイミングを比べられます。</p><p><a href="/study/samples/graphics/frame-generation-observation/index.html" target="_self">フレーム生成の比較デモを開く</a></p><h2 id="アップスケーリングは画素を、フレーム生成は表示枚数を増やす" tabindex="-1">アップスケーリングは画素を、フレーム生成は表示枚数を増やす <a class="header-anchor" href="#アップスケーリングは画素を、フレーム生成は表示枚数を増やす" aria-label="Permalink to &quot;アップスケーリングは画素を、フレーム生成は表示枚数を増やす&quot;">​</a></h2><p><a href="/study/graphics/postprocess/upscaling.html">アップスケーリング</a>では、例えば1280×720で描いた画像から、1920×1080の画像を作ります。TAAUのように過去フレームを使う方式でも、目的は一つの描画時刻の画像を細かい画素で出力することです。</p><p>フレーム生成では、例えば1920×1080の描画済みフレームAとBから、その間の時刻の1920×1080の画像を作ります。画面に出す順序はA、中間フレーム、Bです。両方を使う構成では、例えばアップスケーリング済みのAとBをフレーム生成に渡せます。 <a href="https://gpuopen.com/manuals/fidelityfx_sdk/techniques/super-resolution-interpolation/" target="_blank" rel="noreferrer">AMDのFSR 3資料</a> · <a href="https://developer.nvidia.com/rtx/dlss" target="_blank" rel="noreferrer">NVIDIAのDLSS機能一覧</a></p>',7)),(r(),n(o,null,{default:e(()=>[s(E,{id:"mermaid-21",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20S%5B%22%E3%82%A2%E3%83%83%E3%83%97%E3%82%B9%E3%82%B1%E3%83%BC%E3%83%AA%E3%83%B3%E3%82%B0%EF%BC%9A1%E6%9E%9A%E3%81%82%E3%81%9F%E3%82%8A%E3%81%AE%E7%94%BB%E7%B4%A0%E6%95%B0%22%5D%0A%20%20%20%20%20%20%20%20S0%5B%22A%E3%82%921280%20%C3%97%20720%E3%81%A7%E6%8F%8F%E3%81%8F%22%5D%20--%3E%20S1%5B%22%E5%90%8C%E3%81%98%E6%99%82%E5%88%BB%E3%81%AEA%E3%82%92%3Cbr%2F%3E1920%20%C3%97%201080%E3%81%AB%E5%86%8D%E6%A7%8B%E6%88%90%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20F%5B%22%E3%83%95%E3%83%AC%E3%83%BC%E3%83%A0%E7%94%9F%E6%88%90%EF%BC%9A%E8%A1%A8%E7%A4%BA%E3%81%99%E3%82%8B%E6%9E%9A%E6%95%B0%22%5D%0A%20%20%20%20%20%20%20%20F0%5B%221920%20%C3%97%201080%E3%81%AE%3Cbr%2F%3E%E6%8F%8F%E7%94%BB%E3%83%95%E3%83%AC%E3%83%BC%E3%83%A0%20A%E3%83%BBB%22%5D%20--%3E%20F1%5B%22A%20%E2%86%92%20%E4%B8%AD%E9%96%93%20%E2%86%92%20B%3Cbr%2F%3E%E5%90%84%E3%83%95%E3%83%AC%E3%83%BC%E3%83%A0%E3%81%AF1920%20%C3%97%201080%22%5D%0A%20%20%20%20end%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="_2枚から間の画像を作る" tabindex="-1">2枚から間の画像を作る <a class="header-anchor" href="#_2枚から間の画像を作る" aria-label="Permalink to &quot;2枚から間の画像を作る&quot;">​</a></h2><p>同じ物体がフレームAでは横位置20、フレームBでは横位置40にあるとします。一定の速さで動いたと仮定すれば、中間の位置は <code>(20 + 40) / 2 = 30</code> です。画素ごとの単純な色の平均では、位置20と40に物体が半透明で重なり得ます。動きを補間して位置30に物体を描くと、途中の位置を見せられます。</p><p>実際のゲームには同時に動く面がいくつもあります。エンジンの<strong>モーションベクトル</strong>は、描いた面の画面上の移動を表します。<strong>オプティカルフロー</strong>は、2枚の画像の模様の変化から画面上の動きを推定します。フレーム生成はこうした情報から中間時刻の各画素に対応するAとBの座標を探し、どちらの色を使うか決めます。深度や遮蔽の情報があると、手前と奥の色を区別しやすくなります。 <a href="https://gpuopen.com/manuals/fidelityfx_sdk/techniques/frame-interpolation/" target="_blank" rel="noreferrer">AMDのFidelityFX Frame Interpolation 1.1.3</a> · <a href="https://gpuopen.com/manuals/fsr_sdk/techniques/frame-interpolation-ml/" target="_blank" rel="noreferrer">AMDのFSR Frame Generation 4.0.2</a></p>',3)),(r(),n(o,null,{default:e(()=>[s(E,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22A%3Cbr%2F%3E%E7%89%A9%E4%BD%93%E3%81%AF%E4%BD%8D%E7%BD%AE20%22%5D%20--%3E%20M%5B%22%E5%8B%95%E3%81%8D%E3%82%92%E6%8E%A8%E5%AE%9A%E3%81%97%3Cbr%2F%3E%E4%B8%AD%E9%96%93%E3%81%AE%E5%BA%A7%E6%A8%99%E3%81%B8%E5%AF%BE%E5%BF%9C%E3%81%A5%E3%81%91%E3%82%8B%22%5D%0A%20%20%20%20B%5B%22B%3Cbr%2F%3E%E7%89%A9%E4%BD%93%E3%81%AF%E4%BD%8D%E7%BD%AE40%22%5D%20--%3E%20M%0A%20%20%20%20V%5B%22%E3%82%A8%E3%83%B3%E3%82%B8%E3%83%B3%E3%81%AE%E5%8B%95%E3%81%8D%E3%83%BB%E7%94%BB%E5%83%8F%E3%81%AE%E5%8B%95%E3%81%8D%3Cbr%2F%3E%E6%B7%B1%E5%BA%A6%E3%81%AA%E3%81%A9%22%5D%20--%3E%20M%0A%20%20%20%20M%20--%3E%20H%5B%22%E6%89%8B%E5%89%8D%E3%81%A8%E5%A5%A5%E3%82%92%E8%A6%8B%E5%88%86%E3%81%91%3Cbr%2F%3E%E4%BD%BF%E3%81%88%E3%82%8B%E8%89%B2%E3%82%92%E9%81%B8%E3%81%B6%22%5D%0A%20%20%20%20H%20--%3E%20O%5B%22%E4%B8%AD%E9%96%93%E7%94%BB%E5%83%8F%3Cbr%2F%3E%E7%89%A9%E4%BD%93%E3%81%AF%E4%BD%8D%E7%BD%AE30%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p>物体が動いて新しく見えた背景には、片方の画像にしか色がないことがあります。急なカメラ切り替えでは、2枚の対応を取れないこともあります。動きや遮蔽を取り違えると、輪郭のゆがみ、二重像、穴が出ます。文字や照準をシーンと一緒に補間すると文字もゆがむため、UIを別に合成できる実装があります。 <a href="https://gpuopen.com/manuals/fidelityfx_sdk/techniques/frame-interpolation/" target="_blank" rel="noreferrer">AMDの補間アルゴリズム</a> · <a href="https://github.com/NVIDIA-RTX/Streamline/blob/main/docs/ProgrammingGuideDLSS_G.md" target="_blank" rel="noreferrer">NVIDIA Streamlineのフレーム生成統合ガイド</a></p><h2 id="滑らかさと入力への反応は別々に見る" tabindex="-1">滑らかさと入力への反応は別々に見る <a class="header-anchor" href="#滑らかさと入力への反応は別々に見る" aria-label="Permalink to &quot;滑らかさと入力への反応は別々に見る&quot;">​</a></h2><p>中間フレームを作るには、後ろ側の描画フレームBが必要です。AとBの間に中間フレームを表示するために、Bが完成してから、表示する順序と間隔を調整します。表示間隔が不均等なら、表示枚数が増えても動きがカクついて見えることがあります。 <a href="https://gpuopen.com/manuals/fsr_sdk/techniques/frame-interpolation-swap-chain/" target="_blank" rel="noreferrer">AMDのFrame Generation Swapchain</a> · <a href="/study/graphics/optimization/frame-pacing.html">フレームペーシング</a></p><p>この実践では、入力を反映する基礎フレームを約33.3 msごとに用意します。生成オンでは1基礎フレーム分、表示の予定を後ろへずらします。入力がBで色を変えた例を図にします。中間の位置は補間し、色の切り替えはBが表示される時点にそろえています。</p>',4)),(r(),n(o,null,{default:e(()=>[s(E,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20I%5B%22%E8%89%B2%E3%82%92%E5%88%87%E3%82%8A%E6%9B%BF%E3%81%88%E3%82%8B%E5%85%A5%E5%8A%9B%22%5D%20--%3E%20B%5B%22%E6%AC%A1%E3%81%AE%E5%9F%BA%E7%A4%8E%E3%83%95%E3%83%AC%E3%83%BC%E3%83%A0%20B%20%E3%81%8C%E5%AE%8C%E6%88%90%3Cbr%2F%3E%E5%9F%BA%E7%A4%8E%E6%9B%B4%E6%96%B0%E3%81%AE%E6%99%82%E5%88%BB%E3%81%AF%E4%B8%A1%E3%83%A2%E3%83%BC%E3%83%89%E3%81%A7%E5%85%B1%E9%80%9A%22%5D%0A%20%20%20%20B%20--%3E%20N%5B%22%E3%82%AA%E3%83%95%3Cbr%2F%3EB%E3%82%92%E3%81%99%E3%81%90Canvas%E3%81%AB%E5%8F%8D%E6%98%A0%22%5D%0A%20%20%20%20B%20--%3E%20Y%5B%22%E3%82%AA%E3%83%B3%3Cbr%2F%3EA%E3%81%A8%E4%B8%AD%E9%96%93%E3%83%95%E3%83%AC%E3%83%BC%E3%83%A0%E3%81%AE%E8%A1%A8%E7%A4%BA%E6%9E%A0%E3%82%92%E8%A8%AD%E3%81%91%E3%82%8B%22%5D%0A%20%20%20%20Y%20--%3E%20D%5B%22%E7%B4%8433.3%20ms%E5%BE%8C%E3%81%AE%E8%A1%A8%E7%A4%BA%E6%9E%A0%E3%81%A7%3Cbr%2F%3EB%E3%81%AE%E8%89%B2%E3%82%92Canvas%E3%81%AB%E5%8F%8D%E6%98%A0%22%5D%0A"})]),fallback:e(()=>[...a[2]||(a[2]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p>補間によって表示する位置は増えます。入力を読み、新しいゲーム状態を計算する回数は、ゲーム側の更新ループで決まります。実際のゲームでは、補間画像にもBに反映された変化が一部見える場合があります。入力への反応は、基礎FPS、レンダーキュー、生成処理、表示装置などを含む経路で測ります。デモの約33.3 msは、比較のために設定した表示待ちです。 <a href="/study/graphics/optimization/input-to-display-latency.html">入力から画面に出るまでの遅延</a> · <a href="https://developer.nvidia.com/performance-rendering-tools/reflex" target="_blank" rel="noreferrer">NVIDIA Reflexの開発者向け資料</a></p><h2 id="dlssとfsrで設定を読む" tabindex="-1">DLSSとFSRで設定を読む <a class="header-anchor" href="#dlssとfsrで設定を読む" aria-label="Permalink to &quot;DLSSとFSRで設定を読む&quot;">​</a></h2><p>NVIDIAのDLSSでは、<strong>Super Resolution</strong>が1枚の解像度を上げ、<strong>Frame Generation</strong>や<strong>Multi Frame Generation</strong>が間の画像を増やします。AMDのFSR 3.1ではアップスケーリングとフレーム生成のAPIが分かれ、対応する別のアップスケーラーとフレーム生成を組み合わせられます。AMD FSR Frame Generation 4.0.2は、動き情報と前後の画像を使う学習モデルを採用しています。各機能の対応GPUや設定は、使用する版ごとに確認します。 <a href="https://developer.nvidia.com/rtx/dlss" target="_blank" rel="noreferrer">NVIDIAのDLSS機能一覧</a> · <a href="https://gpuopen.com/manuals/fidelityfx_sdk/getting-started/migrating-to-fsr-3-1/" target="_blank" rel="noreferrer">AMDのFSR 3.1移行ガイド</a> · <a href="https://gpuopen.com/manuals/fsr_sdk/techniques/frame-interpolation-ml/" target="_blank" rel="noreferrer">AMD FSR Frame Generation 4.0.2</a></p><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li><p>30 FPSで描いたフレームの間に1枚ずつ挿入すると、何の頻度が約60回毎秒になりますか。</p><details class="details custom-block"><summary>解答</summary><p>画面へ出す画像の頻度です。ゲームが入力を読んで状態を更新する頻度は、ゲーム側の更新ループで決まります。</p></details></li><li><p>Aで位置20、Bで位置40にある物体を、単純な色の平均で補間すると何が起きますか。</p><details class="details custom-block"><summary>解答</summary><p>Aの位置20とBの位置40にそれぞれ物体の色があり、平均を取ると両方の位置に薄く残り得ます。動きを使う補間なら、物体が通る中間の位置を推定できます。</p></details></li><li><p>デモで生成をオンにすると、色が変わるまで何の待ち時間が加わりますか。</p><details class="details custom-block"><summary>解答</summary><p>入力を反映した基礎フレームの完成から、その画像を表示用Canvasに反映するまでの予定待ちが加わります。中間フレームのためにこの実践で設けた待ちです。</p></details></li></ol><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/graphics/postprocess/upscaling.html">アップスケーリング</a>で、1枚あたりの画素を増やす方法を確認する。</li><li><a href="/study/graphics/optimization/input-to-display-latency.html">入力から画面に出るまでの遅延</a>で、入力からディスプレイまでの待ちを分ける。</li><li><a href="/study/graphics/optimization/frame-pacing.html">フレームペーシング</a>で、表示枚数と表示間隔の関係を整理する。</li><li><a href="/study/practice/graphics/frame-pacing-observation.html">フレームペーシングの実践</a>で、同じ生成フレームを出しても提示間隔によって動きがどう変わるかを比べる。</li><li><a href="/study/learn/roadmap.html?node=gfx-postprocess#graphics">3DCG・描画ロードマップの「ポストプロセスとAA」</a></li></ul><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://gpuopen.com/manuals/fidelityfx_sdk/techniques/frame-interpolation/" target="_blank" rel="noreferrer">AMD — FidelityFX Frame Interpolation 1.1.3</a></li><li><a href="https://gpuopen.com/manuals/fsr_sdk/techniques/frame-interpolation-ml/" target="_blank" rel="noreferrer">AMD — FSR Frame Generation 4.0.2</a> · <a href="https://gpuopen.com/manuals/fsr_sdk/techniques/frame-interpolation-swap-chain/" target="_blank" rel="noreferrer">Frame Generation Swapchain</a></li><li><a href="https://github.com/NVIDIA-RTX/Streamline/blob/main/docs/ProgrammingGuideDLSS_G.md" target="_blank" rel="noreferrer">NVIDIA — Streamline DLSS Frame Generation Integration Guide</a></li></ul>',9))])}const _=l(m,[["render",B]]);export{D as __pageData,_ as default};
